/// <reference lib="webworker" />
import { clientsClaim } from 'workbox-core';
import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

declare let self: ServiceWorkerGlobalScope;

// Self claim to take control immediately
self.skipWaiting();
clientsClaim();

// Cleanup old caches
cleanupOutdatedCaches();

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);

// Cache Google Fonts
registerRoute(
  /^https:\/\/fonts\.googleapis\.com\/.*/i,
  new CacheFirst({
    cacheName: 'google-fonts-cache',
    plugins: [
      new CacheableResponsePlugin({ statuses: [0, 200] }),
      new ExpirationPlugin({ maxEntries: 10, maxAgeSeconds: 60 * 60 * 24 * 365 })
    ]
  })
);

// Cache only Supabase Storage (public assets) — NEVER cache auth/RPC/data endpoints
// Sensitive data (payments, student info) must not persist in Cache Storage
registerRoute(
  /^https:\/\/.*\.supabase\.co\/storage\/.*/i,
  new CacheFirst({
    cacheName: 'supabase-storage-cache',
    plugins: [
      new CacheableResponsePlugin({ statuses: [0, 200] }),
      new ExpirationPlugin({ maxEntries: 30, maxAgeSeconds: 60 * 60 * 24 * 7 })
    ],
  })
);

// Cache images
registerRoute(
  /\.(?:png|jpg|jpeg|svg|gif|webp)$/,
  new CacheFirst({
    cacheName: 'images-cache',
    plugins: [
      new ExpirationPlugin({ maxEntries: 60, maxAgeSeconds: 60 * 60 * 24 * 30 })
    ]
  })
);

// ========================================
// PUSH NOTIFICATION HANDLERS
// ========================================

// Push event - when a push notification is received from server
self.addEventListener('push', (event) => {
  console.log('[SW] Push event received:', event);
  
  let data = {
    title: 'Payvexo',
    body: 'You have a new notification',
    icon: '/app-icon.png',
    badge: '/app-icon.png',
    tag: 'general',
    data: {
      url: '/'
    }
  };
  
  // Parse push payload
  if (event.data) {
    try {
      const payload = event.data.json();
      data = { ...data, ...payload };
    } catch (e) {
      console.error('[SW] Error parsing push data:', e);
      data.body = event.data.text();
    }
  }
  
  const options: NotificationOptions = {
    body: data.body,
    icon: data.icon || '/app-icon.png',
    badge: data.badge || '/app-icon.png',
    tag: data.tag || 'general',
    // vibrate is supported in service workers but not in TS NotificationOptions
    data: data.data || { url: '/' },
    requireInteraction: (data as { requireInteraction?: boolean }).requireInteraction || false,
  };
  
  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

// Notification click - when user clicks on a notification
self.addEventListener('notificationclick', (event) => {
  console.log('[SW] Notification clicked:', event);

  event.notification.close();

  let urlToOpen = event.notification.data?.url || '/';

  // Handle action clicks
  if (event.action === 'dismiss') {
    return;
  }

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      // Multi-tenant prefix: payment/claim notifications are sent with
      // bare paths like /payment/abc or /dashboard. Those 404 inside an
      // org because the actual route is /<orgSlug>/payment/abc. If we
      // have an open window already, lift its org slug from the URL
      // and prefix unprefixed paths. /<orgSlug>/ wins over a bare /.
      try {
        const orgSlug = (() => {
          for (const c of clientList) {
            try {
              const u = new URL(c.url);
              const seg = u.pathname.split('/').filter(Boolean)[0];
              // First path segment is the org slug when it's not a
              // top-level marketing route. Treat known top-level
              // segments as "no org slug".
              if (seg && !['login', 'signup', 'platform', 'create-organization', 'reset-password'].includes(seg)) {
                return seg;
              }
            } catch { /* ignore malformed client URL */ }
          }
          return null;
        })();

        if (orgSlug && urlToOpen.startsWith('/') && !urlToOpen.startsWith(`/${orgSlug}/`) && urlToOpen !== `/${orgSlug}`) {
          // Also normalise legacy plural paths the same way the in-app
          // notification handler does, so a stale notification still
          // lands on the right page after the prefix is applied.
          if (urlToOpen.startsWith('/payments/') && !urlToOpen.includes('/history')) {
            urlToOpen = `/payment/${urlToOpen.replace('/payments/', '')}`;
          }
          if (urlToOpen.startsWith('/claims/')) {
            const id = urlToOpen.replace('/claims/', '').split('/')[0];
            if (id) urlToOpen = `/claim/${id}/decide`;
          }
          urlToOpen = `/${orgSlug}${urlToOpen}`;
        }
      } catch (e) {
        console.warn('[SW] Failed to apply org prefix to notification URL', e);
      }

      // Check if there's already a window/tab open
      for (const client of clientList) {
        if (client.url.includes(self.location.origin) && 'focus' in client) {
          client.focus();
          if ('navigate' in client) {
            (client as { navigate: (url: string) => void }).navigate(urlToOpen);
          }
          return;
        }
      }
      // If no window is open, open a new one
      if (self.clients.openWindow) {
        return self.clients.openWindow(urlToOpen);
      }
    })
  );
});

// Notification close event
self.addEventListener('notificationclose', (event) => {
  console.log('[SW] Notification closed:', event.notification.tag);
});

// Message event - for communication with the main app
self.addEventListener('message', (event) => {
  console.log('[SW] Message received:', event.data);
  
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

console.log('[SW] Custom service worker with push notifications loaded');
